 <body><main class="shell"><header><div class="brand"><div class="sigil">♜</div><div><h1>DARK FOUNTAIN DEFENSE</h1><p>A five-chapter knight's stand</p></div></div><div class="top-right"><span>CHAPTER <b id="chapterLabel">1 / 5</b></span><span class="health" id="health">♥ ♥ ♥ ♥ ♥</span></div></header>
 <section class="panel"><div class="toolbar"><div class="cards"><button class="card selected" data-type="thorn"><span class="icon">✦</span><span><strong>SHADOW SPIKE</strong><small>Fires down its lane</small></span><span class="cost">50 ◈</span></button><button class="card" data-type="gate"><span class="icon">◈</span><span><strong>IRON WARD</strong><small>Holds the line</small></span><span class="cost">35 ◈</span></button><button class="card" data-type="well"><span class="icon">☼</span><span><strong>SOUL WELL</strong><small>Creates dark shards</small></span><span class="cost">75 ◈</span></button></div><div class="stats"><span class="stat">SHARDS <b class="shards" id="energy">125</b></span><button class="round-btn" id="pause" title="Pause">Ⅱ</button></div></div><div class="stage-wrap"><canvas class="stage" id="game" width="1100" height="570" aria-label="Dark Fountain Defense game board"></canvas><div class="toast" id="toast"></div><div class="modal" id="modal"><div class="dialog"><div class="eyebrow" id="eyebrow">A DELTARUNE-INSPIRED FAN GAME</div><h2 id="modalTitle">THE DARK<br>FOUNTAIN STIRS</h2><p id="modalText">The Roaring Knight stands against the Light. Place shadow devices across the lanes, gather dark shards, and keep the invaders from reaching the Fountain.</p><div class="progress" id="progress"></div><button class="primary" id="start">ENTER THE DARK</button></div></div></div><div class="bottom"><span><b>MOVE</b> WASD / arrows &nbsp; <b>SLASH</b> Space &nbsp; <b>BUILD</b> choose a card, click a tile</span><span>Click floating ◈ shards to collect</span></div></section></main>
 <script>
+(()=>{
+const c=document.getElementById('game'),ctx=c.getContext('2d'),W=1100,H=570,modal=document.getElementById('modal'),title=document.getElementById('modalTitle'),text=document.getElementById('modalText'),eyebrow=document.getElementById('eyebrow'),startBtn=document.getElementById('start'),progressEl=document.getElementById('progress'),energyEl=document.getElementById('energy'),healthEl=document.getElementById('health'),chapterEl=document.getElementById('chapterLabel'),toastEl=document.getElementById('toast');
+const levels=[['THE QUIET GARDEN','The first Lightners slip through the old garden. Hold five lanes and learn the Knight’s rhythm.'],['THE CRYSTAL PASS','A frozen pass, a sharper army. The Fountain hums beneath the ice.'],['CLOCKWORK RUINS','Forgotten gears awaken. Armored intruders can take a beating.'],['THE BLACKENED SEA','The tide carries more than wreckage. Protect the shore.'],['THE ROARING END','The Knight faces the final surge. No retreat from the Fountain.']];
+let unlocked=Number(localStorage.getItem('dfd-unlocked')||1),level=1,selected='thorn',energy=125,life=5,entities=[],bullets=[],sparks=[],keys={},running=false,paused=false,mode='menu',spawned=0,total=0,spawnClock=0,last=0,gameTime=0,player={x:125,lane:2,hurt:0,slash:0},devices=[],shards=[],toastTimer=0;
+const rowY=l=>137+l*83, colX=col=>155+col*96;
+function updateHUD(){energyEl.textContent=energy;healthEl.textContent='♥ '.repeat(Math.max(0,life)).trim()+(life?'':'♡');chapterEl.textContent=level+' / 5'}
+function showToast(s){toastEl.textContent=s;toastEl.classList.add('show');toastTimer=1.6}
+function showMenu(kind){mode=kind;paused=false;modal.classList.remove('hidden');progressEl.innerHTML='';for(let i=1;i<=5;i++){let d=document.createElement('span');d.className='dot '+(i<unlocked?'done ':'')+(i===level?'active':'');d.textContent=i;progressEl.append(d)}
+if(kind==='menu'){eyebrow.textContent='A DELTARUNE-INSPIRED FAN GAME';title.innerHTML='THE DARK<br>FOUNTAIN STIRS';text.textContent='The Roaring Knight stands against the Light. Place shadow devices across the lanes, gather dark shards, and keep the invaders from reaching the Fountain.';startBtn.textContent='ENTER THE DARK'}
+if(kind==='level'){eyebrow.textContent='CHAPTER '+level+' · '+(level===5?'FINAL STAND':'THE DARK WORLD');title.textContent=levels[level-1][0];text.textContent=levels[level-1][1]+' Build a defense, then fight beside it.';startBtn.textContent='BEGIN CHAPTER'}
+if(kind==='win'){eyebrow.textContent='CHAPTER CLEARED';title.textContent=level===5?'THE FOUNTAIN ENDURES':'THE LIGHT RETREATS';text.textContent=level===5?'The final wave is broken. The Roaring Knight’s Fountain remains unchallenged—for now.':'The lane is secure. Your devices held, and the Knight survives to face the next chapter.';startBtn.textContent=level===5?'PLAY AGAIN':'NEXT CHAPTER'}
+if(kind==='lose'){eyebrow.textContent='THE LINE HAS FALLEN';title.textContent='THE LIGHT ADVANCES';text.textContent='Invaders broke through the last defense. Rebuild your formation, gather shards, and try this chapter again.';startBtn.textContent='RETRY CHAPTER'}
+if(kind==='pause'){eyebrow.textContent='THE DARK WORLD WAITS';title.textContent='PAUSED';text.textContent='Take a breath, Knight. Your defenses will wait here.';startBtn.textContent='RESUME';} }
+function begin(){if(mode==='pause'){modal.classList.add('hidden');paused=false;running=true;last=performance.now();return}if(mode==='win'&&level<5)level++;else if(mode==='win'&&level===5){level=1;unlocked=1}if(mode==='menu')level=Math.min(level,unlocked);if(mode==='lose'){resetLevel()}else if(mode==='menu'||mode==='level'||mode==='win')resetLevel();modal.classList.add('hidden');running=true;paused=false;last=performance.now()}
+function resetLevel(){energy=125;life=5;entities=[];bullets=[];devices=[];shards=[];sparks=[];spawned=0;total=7+level*3;spawnClock=1.1;gameTime=0;player={x:125,lane:2,hurt:0,slash:0};updateHUD()}
+startBtn.onclick=begin;document.getElementById('pause').onclick=()=>{if(!running)return;running=false;paused=true;showMenu('pause')};
+document.querySelectorAll('.card').forEach(b=>b.onclick=()=>{document.querySelectorAll('.card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');selected=b.dataset.type});
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+function rounded(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
+function drawBG(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1b1428');sky.addColorStop(.4,'#19152a');sky.addColorStop(1,'#0e1720');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
+// distant fortress silhouette
+ctx.fillStyle='#252038';for(let i=0;i<8;i++){let x=i*165-40,h=70+(i*37%55);ctx.fillRect(x,62-h,100,h+45);ctx.beginPath();ctx.moveTo(x-12,62-h);ctx.lineTo(x+50,30-h);ctx.lineTo(x+110,62-h);ctx.fill();ctx.fillRect(x+35,62-h-26,28,30)}
+ctx.fillStyle='#342341';ctx.beginPath();ctx.moveTo(500,120);ctx.lineTo(545,12);ctx.lineTo(590,120);ctx.fill();ctx.fillStyle='#bb66ff';ctx.shadowColor='#ad4eff';ctx.shadowBlur=22;ctx.beginPath();ctx.arc(545,40,9,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;
+// ground lanes
+for(let l=0;l<5;l++){let y=98+l*83;ctx.fillStyle=l%2?'#202337':'#242438';ctx.fillRect(18,y,1064,75);ctx.fillStyle=l%2?'#2d293b':'#302a3b';ctx.fillRect(18,y+59,1064,16);ctx.strokeStyle='#50445a';ctx.globalAlpha=.6;ctx.beginPath();ctx.moveTo(18,y+74);ctx.lineTo(1082,y+74);ctx.stroke();ctx.globalAlpha=1;
+for(let col=0;col<9;col++){let x=108+col*108;ctx.fillStyle=(col+l)%2?'#ffffff05':'#00000009';ctx.fillRect(x,y,104,72);ctx.strokeStyle='#d6b9ff10';ctx.strokeRect(x,y,104,72)}}
+// fountain glow
+ctx.globalAlpha=.25;ctx.fillStyle='#ba68ff';ctx.fillRect(1055,90,8,425);ctx.globalAlpha=1;ctx.fillStyle='#dab1ff';ctx.fillRect(1056,95,3,415);
+// HUD top on canvas
+ctx.fillStyle='#e2d3f0';ctx.font='bold 12px Space Mono';ctx.fillText(levels[level-1][0],28,29);ctx.fillStyle='#9e91aa';ctx.font='10px Space Mono';ctx.fillText('WAVE '+Math.min(spawned+1,total)+' / '+total,28,50);rounded(240,20,815,12,6,'#ffffff14');rounded(240,20,815*(spawned/total),12,6,'#b16cff');ctx.fillStyle='#b8a9c5';ctx.fillText('THE LIGHTNERS',1004,49)}

