ctx.fillStyle='#e2d3f0';ctx.font='bold 12px Space Mono';ctx.fillText(levels[level-1][0],28,29);ctx.fillStyle='#9e91aa';ctx.font='10px Space Mono';ctx.fillText('WAVE '+Math.min(spawned+1,total)+' / '+total,28,50);rounded(240,20,815,12,6,'#ffffff14');rounded(240,20,815*(spawned/total),12,6,'#b16cff');ctx.fillStyle='#b8a9c5';ctx.fillText('THE LIGHTNERS',1004,49)}
function drawDevice(d){let y=rowY(d.lane),x=d.x;ctx.save();ctx.translate(x,y+47);ctx.shadowColor=d.type==='well'?'#f2be59':'#a668ff';ctx.shadowBlur=12;
if(d.type==='thorn'){ctx.fillStyle='#473458';ctx.beginPath();ctx.ellipse(0,14,30,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#3e3151';ctx.beginPath();ctx.moveTo(-20,12);ctx.lineTo(-8,-3);ctx.lineTo(-1,11);ctx.lineTo(9,-10);ctx.lineTo(18,12);ctx.fill();ctx.fillStyle='#dfb8ff';ctx.beginPath();ctx.moveTo(4,-4);ctx.lineTo(24,-11);ctx.lineTo(15,1);ctx.fill();ctx.fillStyle='#b371ff';ctx.beginPath();ctx.arc(4,4,4,0,Math.PI*2);ctx.fill()}
