if(d.type==='well'){ctx.shadowBlur=14;ctx.fillStyle='#51412f';ctx.beginPath();ctx.ellipse(0,9,25,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c985ff';ctx.beginPath();ctx.moveTo(-17,5);ctx.lineTo(-12,-10);ctx.lineTo(-4,-16);ctx.lineTo(4,-16);ctx.lineTo(13,-8);ctx.lineTo(17,5);ctx.closePath();ctx.fill();ctx.fillStyle='#fcdf91';ctx.beginPath();ctx.arc(0,-8,5+Math.sin(gameTime*3)*1.5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff4c4';ctx.beginPath();ctx.arc(-1,-9,2,0,Math.PI*2);ctx.fill()}
ctx.restore();if(d.hp<d.max){ctx.fillStyle='#120e1d';ctx.fillRect(x-20,y+65,40,4);ctx.fillStyle='#ff779b';ctx.fillRect(x-20,y+65,40*d.hp/d.max,4)}}
function drawKnight(x,y,scale=1,foe=false){ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);let c1=foe?'#b9dbe1':'#c8a9f3',c2=foe?'#426978':'#372a50',glow=foe?'#8ff5ee':'#db6eff';ctx.shadowColor=glow;ctx.shadowBlur=10;
// cape
ctx.fillStyle=c2;ctx.beginPath();ctx.moveTo(-13,-5);ctx.lineTo(-25,20);ctx.lineTo(-3,15);ctx.lineTo(12,21);ctx.lineTo(10,-6);ctx.fill();
// body
ctx.fillStyle=foe?'#5e8a94':'#514065';ctx.beginPath();ctx.roundRect(-12,-13,24,27,6);ctx.fill();ctx.fillStyle=c1;ctx.beginPath();ctx.ellipse(0,-24,14,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=foe?'#355c6c':'#41334f';ctx.beginPath();ctx.moveTo(-14,-27);ctx.lineTo(0,-43);ctx.lineTo(14,-27);ctx.lineTo(12,-15);ctx.lineTo(-12,-15);ctx.fill();ctx.fillStyle=glow;ctx.shadowBlur=14;ctx.fillRect(-8,-25,16,3);ctx.fillStyle='#fff';ctx.fillRect(-4,-25,4,2);
// horns
ctx.fillStyle=c1;ctx.beginPath();ctx.moveTo(-11,-31);ctx.lineTo(-22,-45);ctx.lineTo(-17,-25);ctx.fill();ctx.beginPath();ctx.moveTo(11,-31);ctx.lineTo(22,-45);ctx.lineTo(17,-25);ctx.fill();ctx.shadowBlur=0;
// legs
ctx.fillStyle='#b29cc9';ctx.fillRect(-9,9,7,10);ctx.fillRect(3,9,7,10);
if(!foe){ctx.strokeStyle='#e7d8f4';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(12,-7);ctx.lineTo(25,-28);ctx.stroke();ctx.fillStyle='#e3c9ff';ctx.beginPath();ctx.moveTo(25,-28);ctx.lineTo(29,-35);ctx.lineTo(30,-25);ctx.fill()}
ctx.restore()}
function drawEnemy(e){let y=rowY(e.lane);ctx.save();ctx.translate(e.x,y+45);ctx.globalAlpha=e.flash>0?.55:1;if(e.type===2){ctx.fillStyle='#596c78';ctx.shadowColor='#9ce8ff';ctx.shadowBlur=10;ctx.beginPath();ctx.ellipse(0,0,26,21,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b1d5de';ctx.beginPath();ctx.arc(-4,-17,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eaffff';ctx.fillRect(0,-20,11,3);ctx.fillStyle='#263a4d';ctx.fillRect(-20,12,8,7);ctx.fillRect(9,12,8,7)}else{drawKnight(0,0,.78,true)}ctx.globalAlpha=1;if(e.hp<e.max){ctx.fillStyle='#110d18';ctx.fillRect(-19,-36,38,4);ctx.fillStyle='#ff7290';ctx.fillRect(-19,-36,38*e.hp/e.max,4)}ctx.restore()}
function drawPlayer(){let y=rowY(player.lane)+44;drawKnight(player.x,y,1.08);if(player.slash>0){ctx.save();ctx.translate(player.x+18,y-13);ctx.strokeStyle=`rgba(231,205,255,${player.slash*2})`;ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,38,-1.2,.9);ctx.stroke();ctx.restore()}}
function drawShard(s){ctx.save();ctx.translate(s.x,s.y+Math.sin(gameTime*4+s.phase)*5);ctx.rotate(gameTime*1.3);ctx.shadowColor='#8ce9e5';ctx.shadowBlur=14;ctx.fillStyle='#85f4e3';ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(8,0);ctx.lineTo(0,10);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.fillStyle='#eafffb';ctx.fillRect(-1,-5,2,9);ctx.restore()}

