function drawShard(s){ctx.save();ctx.translate(s.x,s.y+Math.sin(gameTime*4+s.phase)*5);ctx.rotate(gameTime*1.3);ctx.shadowColor='#8ce9e5';ctx.shadowBlur=14;ctx.fillStyle='#85f4e3';ctx.beginPath();ctx.moveTo(0,-10);ctx.lineTo(8,0);ctx.lineTo(0,10);ctx.lineTo(-8,0);ctx.closePath();ctx.fill();ctx.fillStyle='#eafffb';ctx.fillRect(-1,-5,2,9);ctx.restore()}
function spawnEnemy(){let lane=Math.floor(Math.random()*5),heavy=level>1&&Math.random()<.18+level*.045,type=heavy?2:1,hp=heavy?5+level*2:2+Math.floor(level*.7);entities.push({x:1090,lane,type,hp,max:hp,speed:heavy?16+level*2:23+level*2,attack:heavy?13:9,flash:0})}
function hitPlayer(){if(player.hurt>0)return;life--;player.hurt=1.5;updateHUD();if(life<=0){running=false;showMenu('lose')}}
function collectShard(s){energy+=25;s.dead=true;updateHUD();showToast('+25 dark shards')}
let shardClock=4;
function update(dt){gameTime+=dt;if(player.hurt>0)player.hurt-=dt;if(player.slash>0)player.slash-=dt;spawnClock-=dt;shardClock-=dt;
if(spawned<total&&spawnClock<=0){spawnEnemy();spawned++;spawnClock=rand(Math.max(.9,2.1-level*.1),Math.max(1.5,3.8-level*.2))}
